"""Check the ACTUAL 7-language buyer request pages generated by build.py.

Offline only, no production deployment. A generated HTML page must never display a
browser-generated 'received' ID when neither the request API nor relay confirmed it.
"""
import os
from pathlib import Path
import unittest

ROOT=Path(__file__).resolve().parents[1]
LANGS=("ko","en","es","fr","ar","vi","id")

@unittest.skipUnless(os.environ.get("WMM_BUYER_GENERATED_QA")=="1","requires isolated static build")
class BuyerGeneratedPreview(unittest.TestCase):
    def test_all_seven_request_routes_have_safe_browser_code(self):
        for lang in LANGS:
            with self.subTest(locale=lang):
                path=ROOT/"dist"/lang/"request"/"index.html"
                self.assertTrue(path.is_file(),f"missing: {path}")
                page=path.read_text(encoding="utf8")
                self.assertIn('action="/nfform?next=/'+lang+'/thanks/"',page)
                self.assertIn('src="/assets/req-safe.js"',page)
                self.assertIn("window.WMM_REQUEST_TEXT=",page)
                self.assertIn('name="privacy_agree"',page)
                self.assertIn('required>',page)
                self.assertNotIn('a.unshift({{id:id',page)
                self.assertNotIn('localStorage.setItem("gv_rq",JSON.stringify(a.slice',page)

    def test_generated_asset_has_fail_closed_request_logic(self):
        asset=ROOT/"dist"/"assets"/"req-safe.js"
        self.assertTrue(asset.is_file(),f"generated asset missing: {asset}")
        code=asset.read_text(encoding="utf8")
        self.assertIn('Request stored on our server.',code)
        self.assertIn('Submission could not be confirmed.',code)
        self.assertIn('Older browser-only record',code)
        self.assertIn('response.status === 503',code)
        self.assertIn('if (!response.ok)',code)
        self.assertIn('if (!r.ok || r.type === "opaque"',code)
        self.assertNotIn('Math.random().toString',code)
        self.assertNotIn('f.submit()',code)

    def test_locale_english_business_pages_exist(self):
        for page in ("index","mdb/index","solutions/index","partners/index",
                     "membership/index","request/index"):
            with self.subTest(page=page):
                path=ROOT/"dist"/"en"/("index.html" if page=="index" else page)
                self.assertTrue(path.is_file(),f"missing: {path}")
        for locale in LANGS:
            with self.subTest(locale=locale):
                self.assertTrue((ROOT/"dist"/locale/"index.html").is_file())

if __name__=="__main__":
    unittest.main()
